questionBody:
### Problem Statement

Implement a function `deepFreeze(obj)` that recursively freezes an object and all nested objects/arrays to guarantee immutability.

```js
const myObject = {
  property1: 'value1',
  nestedObject: { property2: 'value2' }
};
deepFreeze(myObject);
myObject.nestedObject.property2 = 'new value';
console.log(myObject.nestedObject.property2); // 'value2'
```

codeSnippets.code:
function deepFreeze(myObject) {
  for (let [key, value] of Object.entries(myObject)) {
    if (typeof value === 'object' && value !== null) {
      deepFreeze(value);
    }
  }
  return Object.freeze(myObject);
}

Array.prototype.myMap = function(callback, thisArg) {
  if (typeof callback !== 'function') throw new TypeError(callback + ' is not a function');
  const res = [];
  for (let i = 0; i < this.length; i++) {
    if (i in this) {
      res[i] = callback.call(thisArg, this[i], i, this);
    }
  }
  return res;
};
